package com.pochi.astar;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

/**
 * Entry point. Boots a libGDX headless application (no graphics / audio / GL)
 * that reads a weighted grid map and prints the minimum cost path between the
 * configured start and goal cells.
 */
public final class Main {

    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Usage: gdx-astar <map-file-path>");
            System.exit(1);
            return;
        }

        String mapFilePath = args[0];

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // We do all of our work once in create() and then exit; no periodic
        // update/render loop is needed for this command line tool.
        config.updatesPerSecond = -1;

        new HeadlessApplication(new PathfinderApplication(mapFilePath), config);
    }

    private Main() {
    }
}

package com.pochi.astar;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.FileReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Parses and represents a weighted grid map, as described in the task's
 * "Input file format" section.
 */
public final class GridMap {

    public final int rows;
    public final int cols;
    public final int startRow;
    public final int startCol;
    public final int goalRow;
    public final int goalCol;

    /** true if the cell is a wall ('#'). */
    private final boolean[][] wall;
    /** terrain cost (1-9) for open cells; undefined (0) for walls. */
    private final int[][] cost;

    private GridMap(int rows, int cols, int startRow, int startCol, int goalRow, int goalCol,
                     boolean[][] wall, int[][] cost) {
        this.rows = rows;
        this.cols = cols;
        this.startRow = startRow;
        this.startCol = startCol;
        this.goalRow = goalRow;
        this.goalCol = goalCol;
        this.wall = wall;
        this.cost = cost;
    }

    public static GridMap load(String path) throws IOException {
        List<String> lines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }
        }

        int idx = 0;
        String[] dims = splitInts(lines.get(idx++));
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        String[] startTok = splitInts(lines.get(idx++));
        int startRow = Integer.parseInt(startTok[0]);
        int startCol = Integer.parseInt(startTok[1]);

        String[] goalTok = splitInts(lines.get(idx++));
        int goalRow = Integer.parseInt(goalTok[0]);
        int goalCol = Integer.parseInt(goalTok[1]);

        boolean[][] wall = new boolean[rows][cols];
        int[][] cost = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            String rowLine = idx < lines.size() ? lines.get(idx++) : "";
            // Guard against trailing carriage returns from CRLF files.
            rowLine = stripTrailingCr(rowLine);
            for (int c = 0; c < cols; c++) {
                char ch = c < rowLine.length() ? rowLine.charAt(c) : '#';
                if (ch == '#') {
                    wall[r][c] = true;
                } else {
                    wall[r][c] = false;
                    cost[r][c] = ch - '0';
                }
            }
        }

        return new GridMap(rows, cols, startRow, startCol, goalRow, goalCol, wall, cost);
    }

    private static String stripTrailingCr(String s) {
        if (!s.isEmpty() && s.charAt(s.length() - 1) == '\r') {
            return s.substring(0, s.length() - 1);
        }
        return s;
    }

    private static String[] splitInts(String line) {
        return line.trim().split("\\s+");
    }

    public boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isWall(int r, int c) {
        return wall[r][c];
    }

    public int terrainCost(int r, int c) {
        return cost[r][c];
    }
}

package com.pochi.astar;

import com.badlogic.gdx.utils.BinaryHeap;

/**
 * A single grid cell as tracked by the A* search frontier. This is the
 * required custom subclass of {@link com.badlogic.gdx.utils.BinaryHeap.Node}
 * used as the open-set entry for {@link AStarSearch}.
 */
final class CellNode extends BinaryHeap.Node {

    final int row;
    final int col;

    /** Best known cost from the search source to this cell (double precision). */
    double g = Double.POSITIVE_INFINITY;

    /** Whether this node has been finalized (popped and fully relaxed). */
    boolean closed = false;

    CellNode(int row, int col) {
        // The BinaryHeap.Node value (float) is only used to drive the heap's
        // internal ordering; authoritative cost bookkeeping is done with the
        // double-precision 'g' field above.
        super(0f);
        this.row = row;
        this.col = col;
    }
}

package com.pochi.astar;

import com.badlogic.gdx.utils.BinaryHeap;

/**
 * Weighted A* search over the 8-connected weighted grid described by
 * {@link GridMap}. The open set / frontier is a min-priority queue built on
 * top of {@link com.badlogic.gdx.utils.BinaryHeap}, using {@link CellNode} as
 * the custom node type (never {@code java.util.PriorityQueue} or any other
 * JDK tree/heap collection).
 *
 * <p>This search always runs to completion (the frontier is drained
 * entirely) rather than stopping as soon as a single target is reached. That
 * is required here because the caller needs the true shortest-path distance
 * from every reachable cell back to the search's source cell, so that the
 * lexicographically-smallest optimal path can later be reconstructed greedily
 * (see {@link PathfinderApplication}). An optional heuristic (octile
 * distance to a reference cell, scaled by the minimum possible per-step
 * terrain cost) is used to order the frontier; when no reference cell is
 * supplied the heuristic is identically zero and the search degenerates to
 * plain Dijkstra, itself a valid special case of weighted A*.
 */
final class AStarSearch {

    /** Smallest possible terrain digit, used to keep the heuristic admissible. */
    private static final double MIN_TERRAIN_COST = 1.0;
    private static final double SQRT2 = Math.sqrt(2.0);

    private final GridMap map;

    AStarSearch(GridMap map) {
        this.map = map;
    }

    /**
     * Runs weighted A* from {@code (srcRow, srcCol)} over the whole grid and
     * returns a {@code double[rows][cols]} array with the minimum path cost
     * from the source to every cell ({@link Double#POSITIVE_INFINITY} for
     * cells that are walls or unreachable).
     *
     * @param heuristicRefRow row of a reference cell used only to bias
     *                        frontier ordering (may be -1 to disable).
     * @param heuristicRefCol column of the reference cell (may be -1 to disable).
     */
    double[][] computeDistances(int srcRow, int srcCol, int heuristicRefRow, int heuristicRefCol) {
        int rows = map.rows;
        int cols = map.cols;

        CellNode[][] nodes = new CellNode[rows][cols];
        double[][] dist = new double[rows][cols];
        for (double[] row : dist) {
            java.util.Arrays.fill(row, Double.POSITIVE_INFINITY);
        }

        if (!map.inBounds(srcRow, srcCol) || map.isWall(srcRow, srcCol)) {
            return dist;
        }

        boolean useHeuristic = heuristicRefRow >= 0 && heuristicRefCol >= 0;

        BinaryHeap<CellNode> open = new BinaryHeap<>();

        CellNode source = new CellNode(srcRow, srcCol);
        nodes[srcRow][srcCol] = source;
        source.g = 0.0;
        open.add(source, (float) heuristic(srcRow, srcCol, heuristicRefRow, heuristicRefCol, useHeuristic));

        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

        while (open.notEmpty()) {
            CellNode current = open.pop();
            if (current.closed) {
                continue;
            }
            current.closed = true;
            dist[current.row][current.col] = current.g;

            for (int dir = 0; dir < 8; dir++) {
                int nr = current.row + dr[dir];
                int nc = current.col + dc[dir];
                if (!map.inBounds(nr, nc) || map.isWall(nr, nc)) {
                    continue;
                }

                boolean diagonal = dr[dir] != 0 && dc[dir] != 0;
                if (diagonal) {
                    // No corner cutting: both orthogonal neighbors must be open.
                    if (map.isWall(current.row, nc) || map.isWall(nr, current.col)) {
                        continue;
                    }
                }

                double moveCost = edgeCost(current.row, current.col, nr, nc, diagonal);
                double candidateG = current.g + moveCost;

                CellNode neighbor = nodes[nr][nc];
                if (neighbor == null) {
                    neighbor = new CellNode(nr, nc);
                    nodes[nr][nc] = neighbor;
                }

                if (neighbor.closed) {
                    continue;
                }

                if (candidateG < neighbor.g) {
                    neighbor.g = candidateG;
                    double f = candidateG + heuristic(nr, nc, heuristicRefRow, heuristicRefCol, useHeuristic);
                    if (open.contains(neighbor, false)) {
                        open.setValue(neighbor, (float) f);
                    } else {
                        open.add(neighbor, (float) f);
                    }
                }
            }
        }

        return dist;
    }

    private double edgeCost(int r1, int c1, int r2, int c2, boolean diagonal) {
        double t1 = map.terrainCost(r1, c1);
        double t2 = map.terrainCost(r2, c2);
        double base = (t1 + t2) / 2.0;
        return diagonal ? SQRT2 * base : base;
    }

    private double heuristic(int r, int c, int refRow, int refCol, boolean enabled) {
        if (!enabled) {
            return 0.0;
        }
        int dr = Math.abs(r - refRow);
        int dc = Math.abs(c - refCol);
        int diag = Math.min(dr, dc);
        int straight = Math.abs(dr - dc);
        // Octile distance lower bound, scaled by the cheapest possible move costs.
        return diag * SQRT2 * MIN_TERRAIN_COST + straight * MIN_TERRAIN_COST;
    }
}

package com.pochi.astar;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;

import java.io.IOException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

/**
 * Drives the whole pathfinding computation from within the libGDX headless
 * application lifecycle. All work happens in {@link #create()}; no
 * rendering, graphics, or audio APIs are touched.
 */
final class PathfinderApplication implements ApplicationListener {

    private static final double EPS = 1e-9;
    private static final double SQRT2 = Math.sqrt(2.0);

    private final String mapFilePath;

    PathfinderApplication(String mapFilePath) {
        this.mapFilePath = mapFilePath;
    }

    @Override
    public void create() {
        try {
            run();
        } catch (IOException e) {
            System.err.println("Failed to read map file: " + e.getMessage());
        } finally {
            Gdx.app.exit();
        }
    }

    private void run() throws IOException {
        GridMap map = GridMap.load(mapFilePath);

        // Full-grid shortest distance to the goal, computed once via a
        // BinaryHeap-backed weighted A* search rooted at the goal cell (the
        // movement/cost model is symmetric, so distance-to-goal equals
        // distance-from-goal). This lets us later greedily rebuild the
        // lexicographically smallest optimal path without a second search.
        AStarSearch search = new AStarSearch(map);
        double[][] distToGoal = search.computeDistances(map.goalRow, map.goalCol, map.startRow, map.startCol);

        double totalCost = distToGoal[map.startRow][map.startCol];
        if (Double.isInfinite(totalCost)) {
            System.out.println("NO PATH");
            return;
        }

        List<int[]> path = reconstructPath(map, distToGoal, totalCost);

        StringBuilder sb = new StringBuilder();
        sb.append("LENGTH ").append(path.size()).append('\n');
        sb.append("COST ").append(formatCost(totalCost)).append('\n');
        sb.append("PATH").append('\n');
        for (int[] cell : path) {
            sb.append(cell[0]).append(',').append(cell[1]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Greedily walks from start to goal. At every step, among all neighbors
     * that continue some minimum-cost path (verified via the precomputed
     * distance-to-goal array), the lexicographically smallest cell (row
     * first, then column) is chosen. Since all edge costs are strictly
     * positive, minimum-cost paths are simple, and picking the smallest
     * viable next cell at each step yields the overall lexicographically
     * smallest optimal path.
     */
    private List<int[]> reconstructPath(GridMap map, double[][] distToGoal, double totalCost) {
        List<int[]> path = new ArrayList<>();
        int r = map.startRow;
        int c = map.startCol;
        path.add(new int[] {r, c});

        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

        while (r != map.goalRow || c != map.goalCol) {
            double remaining = distToGoal[r][c];

            int bestR = -1;
            int bestC = -1;
            double bestMoveCost = 0;

            for (int dir = 0; dir < 8; dir++) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (!map.inBounds(nr, nc) || map.isWall(nr, nc)) {
                    continue;
                }

                boolean diagonal = dr[dir] != 0 && dc[dir] != 0;
                if (diagonal) {
                    if (map.isWall(r, nc) || map.isWall(nr, c)) {
                        continue;
                    }
                }

                double h = distToGoal[nr][nc];
                if (Double.isInfinite(h)) {
                    continue;
                }

                double t1 = map.terrainCost(r, c);
                double t2 = map.terrainCost(nr, nc);
                double base = (t1 + t2) / 2.0;
                double moveCost = diagonal ? SQRT2 * base : base;

                if (Math.abs(moveCost + h - remaining) <= EPS) {
                    if (bestR == -1 || nr < bestR || (nr == bestR && nc < bestC)) {
                        bestR = nr;
                        bestC = nc;
                        bestMoveCost = moveCost;
                    }
                }
            }

            if (bestR == -1) {
                // Should be unreachable given totalCost was finite, but guard
                // defensively against floating point edge cases.
                throw new IllegalStateException("Failed to reconstruct optimal path");
            }

            r = bestR;
            c = bestC;
            path.add(new int[] {r, c});
        }

        return path;
    }

    private static String formatCost(double cost) {
        BigDecimal bd = BigDecimal.valueOf(cost).setScale(4, RoundingMode.HALF_UP);
        return bd.toPlainString();
    }

    @Override
    public void resize(int width, int height) {
    }

    @Override
    public void render() {
    }

    @Override
    public void pause() {
    }

    @Override
    public void resume() {
    }

    @Override
    public void dispose() {
    }
}

